import { NextRequest, NextResponse } from 'next/server'
import { auth } from '@/lib/auth'
import { connectDB } from '@/lib/db'
import { Vendor } from '@/models/vendor'
import { VendorDeliveryRule } from '@/models/vendor-delivery-rule'
import CampusLocation from '@/models/campus-location'
import { isVendorServiceType, normalizeVendorName, validateVendorLocations } from '@/lib/vendors'
async function admin(request: NextRequest) { const session = await auth.api.getSession({ headers: request.headers }); return session?.user?.role === 'admin' ? session : null }
export async function GET(request: NextRequest) { if (!await admin(request)) return NextResponse.json({ error: 'Forbidden' }, { status: 403 }); await connectDB(); const vendors = await Vendor.find().sort({ name: 1 }).lean(); const ids = vendors.map(v => v._id); const [coverage, parents] = await Promise.all([VendorDeliveryRule.aggregate([{ $match: { vendorId: { $in: ids }, enabled: true } }, { $group: { _id: '$vendorId', count: { $sum: 1 } } }]), CampusLocation.find({ _id: { $in: vendors.flatMap(v => [v.pickupParentLocationId, v.pickupExactLocationId].filter(Boolean)) } }).select('name parentLocationId active').lean()]); const byId = new Map(parents.map(p => [String(p._id), p])); const counts = new Map(coverage.map(c => [String(c._id), c.count])); return NextResponse.json({ vendors: vendors.map(v => { const pickup = v.pickupParentLocationId ? byId.get(String(v.pickupParentLocationId)) : null; const covered = counts.get(String(v._id)) || 0; return { ...v, pickupParent: pickup ? { id: String(pickup._id), name: pickup.name, active: pickup.active } : null, coverageCount: covered, readiness: !v.active ? 'inactive' : pickup?.active && covered ? 'ready' : 'needs_setup' } }) }) }
export async function POST(request: NextRequest) { const session = await admin(request); if (!session) return NextResponse.json({ error: 'Forbidden' }, { status: 403 }); try { await connectDB(); const body = await request.json(), name = String(body.name || '').trim(), serviceType = String(body.serviceType || ''); if (!name || !isVendorServiceType(serviceType)) return NextResponse.json({ error: 'Enter a vendor name and valid service type.' }, { status: 400 }); const locations = await validateVendorLocations(body.pickupParentLocationId || null, body.pickupExactLocationId || null); const vendor = await Vendor.create({ name, normalizedName: normalizeVendorName(name), serviceType, pickupParentLocationId: locations.parent?._id || null, pickupExactLocationId: locations.exact?._id || null, businessId: body.businessId || null, active: Boolean(body.active), createdBy: session.user.id, updatedBy: session.user.id }); return NextResponse.json({ vendor }, { status: 201 }) } catch (error) { if ((error as { code?: number }).code === 11000) return NextResponse.json({ error: 'A vendor with this name already exists.' }, { status: 409 }); return NextResponse.json({ error: error instanceof Error ? error.message : 'Unable to create vendor.' }, { status: 400 }) } }
